#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

int n;
vector<vector<int>> tree;

// BFS函数，返回一对 {最远结点, 距离}
pair<int,int> bfs(int start) {
    vector<bool> visited(n+1, false);
    vector<int> dist(n+1, 0);
    queue<int> q;
    q.push(start);
    visited[start] = true;
    while(!q.empty()){
        int u = q.front();
        q.pop();
        for (int v : tree[u]) {
            if (!visited[v]){
                visited[v] = true;
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    int maxNode = start, maxDist = 0;
    for (int i = 1; i <= n; i++){
        if(dist[i] > maxDist){
            maxDist = dist[i];
            maxNode = i;
        }
    }
    return {maxNode, maxDist};
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int counts[26];
    for (int i = 0; i < 26; i++){
        cin >> counts[i];
    }
    cin >> n;
    tree.resize(n+1);
    for (int i = 1; i <= n-1; i++){
        int u, v;
        cin >> u >> v;
        tree[u].push_back(v);
        tree[v].push_back(u);
    }

    // 两次 BFS 求树的直径（以结点数计，直径 = 边数 + 1）
    pair<int,int> first = bfs(1);
    pair<int,int> second = bfs(first.first);
    int diameterEdges = second.second;
    int diameterNodes = diameterEdges + 1;

    // 计算能构成的最长回文串长度 L_max
    int evenSum = 0;
    bool hasOdd = false;
    for (int i = 0; i < 26; i++){
        evenSum += counts[i] - (counts[i] & 1);
        if(counts[i] % 2 == 1)
            hasOdd = true;
    }
    int L_max = evenSum + (hasOdd ? 1 : 0);

    int ans = min(diameterNodes, L_max);
    cout << ans << "\n";
    return 0;
}
```

