# -*- coding: utf-8 -*-
import sys
from collections import deque

def main():
    # 读入26种颜色的数量
    counts = list(map(int, sys.stdin.readline().split()))
    n = int(sys.stdin.readline().strip())

    # 构造树的邻接表
    tree = [[] for _ in range(n+1)]
    for _ in range(n-1):
        u, v = map(int, sys.stdin.readline().split())
        tree[u].append(v)
        tree[v].append(u)

    # 求树的直径：使用两次 BFS
    def bfs(start):
        visited = [False]*(n+1)
        dist = [0]*(n+1)
        q = deque([start])
        visited[start] = True
        while q:
            u = q.popleft()
            for v in tree[u]:
                if not visited[v]:
                    visited[v] = True
                    dist[v] = dist[u] + 1
                    q.append(v)
        # 找到最远的节点及其距离
        max_node = 1
        max_dist = 0
        for i in range(1, n+1):
            if dist[i] > max_dist:
                max_dist = dist[i]
                max_node = i
        return max_node, max_dist

    # 第一次BFS，任选一个结点（例如1）
    u, _ = bfs(1)
    # 第二次BFS，从u出发找到最远点，距离为树的直径（边数）
    v, diameter_edges = bfs(u)
    # 转换成结点数（直径路径上的结点数 = 边数 + 1）
    diameter_nodes = diameter_edges + 1

    # 计算能构成的最长对称序列长度 L_max
    even_sum = 0
    has_odd = False
    for cnt in counts:
